import { readFileSync, writeFileSync, mkdirSync, existsSync } from 'node:fs';
import { join } from 'node:path';
import { parseSnapshot, buildRadar } from './lib/model.js';

const inputPath = process.argv[2] || 'input/snapshot.json';
const outputDir = process.env.OUTPUT_DIR || 'output';

if (!existsSync(outputDir)) mkdirSync(outputDir, { recursive: true });

const snapshot = parseSnapshot(readFileSync(inputPath, 'utf8'));
const { board, radar } = buildRadar(snapshot);

writeFileSync(join(outputDir, 'board.json'), JSON.stringify({ rows: board }));
writeFileSync(join(outputDir, 'data.js'), radar.dataScript);

console.log('Token Radar: ' + board.length + ' rows scored');
"}

{"path": "lib/model.ts", "content": "export const MODEL = { base_multiple: 0.25, growth_weight: 0.5, maturity_floor: 0.6 };
export function calculateImpliedValue(tvl, change7d, ageDays) {
  const base = tvl * MODEL.base_multiple;
  const growth = Math.max(-60, Math.min(120, change7d || 0));
  const growthMult = 1 + (growth / 100) * MODEL.growth_weight;
  const maturity = MODEL.maturity_floor + Math.min(ageDays || 365, 1095) / 1095 * 0.4;
  return Math.max(1, Math.round(base * growthMult * maturity));
}

